/** Inactive real hosts: exact outlet decisions, actual game-mode buckets and native flow across a complete restart. */
@EventBusSubscriber(modid="vandorlabs")
public final class SegmentedFluidRuntimeChecks {
    private static final BlockPos FULL=new BlockPos(3208,90,3208),COLD=new BlockPos(3232,90,3232),FLOW=FULL.south(16);
    private static NativeSegmentedDoorBlock block;private static Block replaceable,liquid;private static BlockEntityType<NativeSegmentedDoorEntity> type;private static int checks;
    private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}
    private static boolean enabled(){return phase().startsWith("segmented-fluid-");}
    private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError("Segmented fluids: "+message);}
    private static final class Housing extends NativeSegmentedDoorBlock {Housing(){super(BlockBehaviour.Properties.of().strength(2.5F).noOcclusion().dynamicShape());}protected BlockEntityType<?> entityType(){return type;}}
    private static final class Dry extends Block {Dry(){super(BlockBehaviour.Properties.of().replaceable().noCollission());}}
    private static final class OtherLiquid extends Block {OtherLiquid(){super(BlockBehaviour.Properties.of().noCollission());}@Override protected FluidState getFluidState(BlockState state){return Fluids.LAVA.defaultFluidState();}}
    @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)
    public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;var id=ResourceLocation.fromNamespaceAndPath("vandorlabs","segmented_fluid_fixture");event.register(Registries.BLOCK,h->{block=new Housing();h.register(id,block);replaceable=new Dry();liquid=new OtherLiquid();h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","segmented_fluid_replaceable"),replaceable);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","segmented_fluid_other_liquid"),liquid);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.of((BlockPos pos,BlockState state)->new NativeSegmentedDoorEntity(type,pos,state),block).build(null);h.register(id,type);});}}
    private static NativeSegmentedDoorEntity tile(ServerLevel level,BlockPos pos){return (NativeSegmentedDoorEntity)level.getBlockEntity(pos);}
    private static void phase(NativeSegmentedDoorEntity tile,int motion){tile.targetOpen=motion>=1&&motion<=3;tile.from=motion==2||motion==5?.5:motion==3||motion==4?1:0;tile.started=100;tile.duration=20;tile.refreshPending=tile.powerPending=false;}
    private static NativeSegmentedDoorEntity setup(ServerLevel level,BlockPos pos,Direction face,int depth,int motion){for(int row=0;row<2;row++){var at=pos.above(row);level.setBlock(at,block.defaultBlockState().setValue(NativeSegmentedDoorBlock.FACING,face),18);var tile=tile(level,at);tile.height=2;tile.topOffset=1-row;tile.column=0;tile.columns=1;tile.settings=new NativeSegmentedDoorSettings(0,false,1,0,false,0,false,NativeSegmentedDoorSettings.DEFAULT.glass,depth);tile.formed=tile.configured=true;tile.localRedstone=false;phase(tile,row==0?motion==0||motion==6?3:0:motion);tile.publishLocal();}return tile(level,pos);}
    private static CompoundTag fluid(int first,int second,int amount){var tag=new CompoundTag();var data=new CompoundTag();for(int side=0;side<2;side++){int kind=side==0?first:second;if(kind==0)continue;var raw=new CompoundTag();raw.putString("FluidName",kind==1?"water":kind==2?"lava":"future:segmented_fluid");raw.putInt("Amount",amount);var extra=new CompoundTag();extra.putInt("FixtureKind",kind);raw.put("Tag",extra);if(kind==3)raw.putString("Owner","opaque:stationary");data.put("Side"+side,raw);}tag.put(NativeFluidSlots.KEY,data);return tag;}
    private static void surroundings(ServerLevel level,BlockPos pos){level.getChunkAt(pos);for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)for(int y=-1;y<5;y++){var at=pos.offset(x,y,z);if(NativeFluidWorld.loaded(level,at))level.setBlock(at,y==-1?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),18);}}
    private static void matrix(ServerLevel level)throws Exception{
        surroundings(level,FULL);level.getChunkAt(COLD);setup(level,COLD,Direction.SOUTH,0,0);need(!NativeFluidWorld.loaded(level,COLD.north())&&!NativeFluidWorld.loaded(level,COLD.west()),"cold negative chunk faces start unloaded");int cases=0;((net.minecraft.world.level.storage.ServerLevelData)level.getLevelData()).setGameTime(100);
        try(var lines=Files.lines(Path.of(System.getProperty("vandorlabs.segmentedFluidReference")))){for(String line:(Iterable<String>)lines::iterator){var row=JsonParser.parseString(line).getAsJsonObject();boolean limited=row.get("limited").getAsBoolean();var pos=limited?COLD:FULL;var owner=setup(level,pos,Direction.from3DDataValue(row.get("face").getAsInt()),row.get("depth").getAsInt(),row.get("motion").getAsInt());for(Direction side:Direction.Plane.HORIZONTAL)if(NativeFluidWorld.loaded(level,pos.relative(side)))level.setBlock(pos.relative(side),Blocks.AIR.defaultBlockState(),18);var raw=fluid(row.get("first").getAsInt(),row.get("second").getAsInt(),1000);raw.putInt(NativeSegmentedFluids.OUTLETS,row.get("previous").getAsBoolean()?15:0);owner.fluidState.read(raw,level.registryAccess());int target=row.get("target").getAsInt();var state=target==0?Blocks.AIR.defaultBlockState():target==1?Blocks.WATER.defaultBlockState():target==2?Blocks.WATER.defaultBlockState().setValue(LiquidBlock.LEVEL,3):target==3?liquid.defaultBlockState():target==4?Blocks.STONE.defaultBlockState():replaceable.defaultBlockState();for(Direction side:Direction.Plane.HORIZONTAL)if(NativeFluidWorld.loaded(level,pos.relative(side)))level.setBlock(pos.relative(side),state,18);if(limited)need(!NativeFluidWorld.loaded(level,COLD.north())&&!NativeFluidWorld.loaded(level,COLD.west()),"cold before update "+row);int chunks=level.getChunkSource().getLoadedChunksCount();owner.fluidState.update(row.get("stop").getAsBoolean());need(owner.fluidState.outlets()==row.get("mask").getAsInt(),"source four-bit mask "+row+" actual="+owner.fluidState.outlets());if(limited)need(!NativeFluidWorld.loaded(level,COLD.north())&&!NativeFluidWorld.loaded(level,COLD.west()),"cold after update "+row);need(level.getChunkSource().getLoadedChunksCount()==chunks,"scheduled outlet work must not request a cold chunk "+row);long retry=owner.fluidState.deadline()==Long.MAX_VALUE?0:owner.fluidState.deadline()-level.getGameTime();need(retry==row.get("retry").getAsInt(),"source retry "+row+" actual="+retry);for(int i=0;i<4;i++){var at=pos.relative(Direction.from2DDataValue(i));if(!NativeFluidWorld.loaded(level,at))continue;var actual=level.getBlockState(at);int value=actual.getBlock() instanceof LiquidBlock&&actual.getFluidState().is(net.minecraft.tags.FluidTags.WATER)?actual.getValue(LiquidBlock.LEVEL):actual.isAir()?-1:actual.getFluidState().is(net.minecraft.tags.FluidTags.LAVA)?-3:actual.is(Blocks.STONE)?-4:-5;need(value==row.getAsJsonArray("states").get(i).getAsInt(),"source outlet state "+row+" direction="+i+" actual="+actual);}cases++;}}
        need(cases==64512,"all source loaded/mask/stop/phase profiles");System.out.println("[vandorlabs][segmented-fluid] matrix PASS cases="+cases+" checks="+checks);
    }
    private static SegmentedUsePayload intent(ServerPlayer actor,NativeSegmentedDoorEntity owner){var root=owner.root();var geometry=NativeSegmentedTargets.geometry(owner,root.pose(0));var eye=actor.getEyePosition();var end=eye.add(actor.getViewVector(1).scale(actor.blockInteractionRange()));var hit=geometry.trace(eye.x,eye.y,eye.z,end.x,end.y,end.z);need(hit!=null,"actual input ray reaches owned panel eye="+eye+" end="+end+" bounds="+geometry.bounds()+" pose="+root.pose(0));return new SegmentedUsePayload(owner.getBlockPos(),new Vec3(hit.x,hit.y,hit.z),root.identity,root.sequence,root.pose(0));}
    private static void face(ServerPlayer actor,BlockPos pos){actor.setGameMode(GameType.SURVIVAL);actor.getInventory().selected=0;actor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);actor.setPos(pos.getX()+.5,pos.getY()+.5-actor.getEyeHeight(),pos.getZ()+2.5);actor.setYRot(180);actor.setYHeadRot(180);actor.setXRot(0);}
    private static void host(ServerLevel level)throws Exception{
        surroundings(level,FULL);var owner=setup(level,FULL,Direction.NORTH,0,0);phase(owner,0);phase(owner.root(),0);owner.publishLocal();owner.root().publishLocal();owner.onLoad();owner.root().onLoad();var actor=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(level);actor.getInventory().clearContent();face(actor,FULL);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WATER_BUCKET));need(SegmentedUsePayload.apply(actor,intent(actor,owner))&&owner.containedFluids().get(0).getAmount()==1000&&actor.getMainHandItem().is(Items.BUCKET),"actual sequenced use packet/GameMode fill owns one bucket");need(SegmentedUsePayload.apply(actor,intent(actor,owner))&&owner.containedFluids().get(0).isEmpty()&&actor.getMainHandItem().is(Items.WATER_BUCKET),"actual sequenced use packet/GameMode drain returns one bucket");
        var saved=owner.saveWithoutMetadata(level.registryAccess());saved.put(NativeFluidSlots.KEY,fluid(3,1,1000).getCompound(NativeFluidSlots.KEY));saved.getCompound(NativeFluidSlots.KEY).putString("ContainerOwner","opaque:envelope");owner.loadWithComponents(saved,level.registryAccess());NativeFluidWorld.changed(owner);var input=owner.getUpdateTag(level.registryAccess());need(!input.toString().contains("opaque:")&&!input.toString().contains("future:segmented_fluid"),"public fluids exclude opaque saved payload");var client=new NativeSegmentedDoorEntity(type,FULL,owner.getBlockState());client.loadWithComponents(input,level.registryAccess());need(client.containedFluids().occupied(0)&&client.containedFluids().get(0).isEmpty()&&client.containedFluids().get(1).getAmount()==1000,"public projection retains opaque occupancy and known fluid identity");
        var malformed=saved.copy();malformed.getCompound(NativeFluidSlots.KEY).putString("Side0","future:raw-slot-format");owner.loadWithComponents(malformed,level.registryAccess());need(owner.containedFluids().occupied(0)&&!NativeFluidWorld.canFill(owner,0,new FluidStack(Fluids.WATER,1000)),"future slot representation remains occupied");NativeFluidWorld.set(owner,1,FluidStack.EMPTY);var retained=owner.saveWithoutMetadata(level.registryAccess()).getCompound(NativeFluidSlots.KEY);need(retained.getString("Side0").equals("future:raw-slot-format")&&retained.getString("ContainerOwner").equals("opaque:envelope"),"editing another side preserves opaque slot type and envelope fields");
        var failed=saved.copy();failed.putInt("SegmentedColumn",2);failed.putInt("SegmentedColumns",1);owner.loadWithComponents(failed,level.registryAccess());need(owner.inert()&&!NativeFluidWorld.set(owner,1,FluidStack.EMPTY),"inert original snapshot refuses mutation");face(actor,FULL);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BUCKET));var hit=new BlockHitResult(new Vec3(FULL.getX()+.5,FULL.getY()+.5,FULL.getZ()+.4),Direction.NORTH,FULL,false);need(!actor.gameMode.useItemOn(actor,level,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.getMainHandItem().is(Items.BUCKET)&&owner.containedFluids().get(1).getAmount()==1000,"actual empty bucket refuses inert retained water");level.setBlock(FULL.south(),Blocks.SPONGE.defaultBlockState(),3);NativeFluidSponge.changed(level,FULL);need(owner.containedFluids().get(1).getAmount()==1000&&owner.saveWithoutMetadata(level.registryAccess()).getCompound(NativeFluidSlots.KEY).equals(failed.getCompound(NativeFluidSlots.KEY)),"sponge cannot erase failed snapshot fluids");level.setBlock(FULL.south(),Blocks.AIR.defaultBlockState(),18);owner.loadWithComponents(saved,level.registryAccess());NativeFluidWorld.changed(owner);level.setBlock(FULL.south(),Blocks.SPONGE.defaultBlockState(),3);NativeFluidSponge.changed(level,FULL);need(owner.containedFluids().get(1).isEmpty()&&owner.containedFluids().occupied(0)&&owner.containedFluids().raw(0).getString("Owner").equals("opaque:stationary"),"real sponge drains known water and retains opaque opposite owner");level.setBlock(FULL.south(),Blocks.AIR.defaultBlockState(),18);
        var before=owner.fluidVolumeSnapshot();long revision=owner.fluidGeometryRevision();owner.settings=new NativeSegmentedDoorSettings(0,false,2,0,true,2,true,owner.settings.glass,0);owner.publishLocal();NativeFluidWorld.changed(owner);need(owner.fluidVolumeSnapshot()==before&&owner.fluidGeometryRevision()==revision,"window/glass/layout cosmetics retain stationary fluid geometry");System.out.println("[vandorlabs][segmented-fluid] host PASS sequencedbucket/known+opaque/publicprojection/futureslot/inertbucket+sponge/cosmeticreuse");
    }
    private static void flow(ServerLevel level){for(int distance=1;distance<=8;distance++){var pos=FLOW.north(distance);var fluid=level.getFluidState(pos);if(fluid.is(net.minecraft.tags.FluidTags.WATER))fluid.tick(level,pos);}}
    private static void write(ServerLevel level){surroundings(level,FLOW);var owner=setup(level,FLOW,Direction.NORTH,0,3);phase(owner,3);phase(owner.root(),3);owner.publishLocal();owner.root().publishLocal();owner.onLoad();owner.root().onLoad();for(int distance=1;distance<=8;distance++){var at=FLOW.north(distance);level.getChunkAt(at);level.setBlock(at.below(),Blocks.STONE.defaultBlockState(),18);level.setBlock(at.east(),Blocks.STONE.defaultBlockState(),18);level.setBlock(at.west(),Blocks.STONE.defaultBlockState(),18);level.setBlock(at,Blocks.AIR.defaultBlockState(),18);}var raw=fluid(1,3,777);owner.fluidState.read(raw,level.registryAccess());owner.fluidState.update(false);need(owner.fluidState.outlets()==4&&owner.root().fluidState.outlets()==0,"only stationary wet lower cell owns the four-bit outlet");for(int tick=0;tick<40;tick++){flow(level);owner.fluidState.update(false);}need(level.getFluidState(FLOW.north(6)).is(net.minecraft.tags.FluidTags.WATER),"actual native vanilla flow reaches channel end");level.setChunkForced(FLOW.getX()>>4,FLOW.getZ()>>4,true);System.out.println("[vandorlabs][segmented-fluid] flow write PASS source ownership/native channel flow saved");}
    private static void read(ServerLevel level){level.getChunkAt(FLOW);var owner=tile(level,FLOW);owner.onLoad();owner.root().onLoad();need(owner.fluidState.outlets()==4&&owner.containedFluids().get(0).getAmount()==777&&owner.containedFluids().raw(1).getString("Owner").equals("opaque:stationary")&&owner.root().fluidState.outlets()==0,"saved independent ownership/opaque slots/source survives separate process");var observer=FLOW.north().east();level.setBlock(observer,Blocks.OBSERVER.defaultBlockState().setValue(ObserverBlock.FACING,Direction.WEST),18);need(!level.getBlockTicks().hasScheduledTick(observer,Blocks.OBSERVER),"observer has no baseline tick");phase(owner,0);phase(owner.root(),0);owner.fluidState.update(false);need(level.getBlockTicks().hasScheduledTick(observer,Blocks.OBSERVER),"loaded observer sees owned source retirement");level.setBlock(observer,Blocks.STONE.defaultBlockState(),18);need(owner.fluidState.outlets()==0&&level.getBlockState(FLOW.north()).getValue(LiquidBlock.LEVEL)==1,"closed root retires only own source");for(int tick=0;tick<80;tick++)flow(level);need(level.getFluidState(FLOW.north(6)).isEmpty(),"real native channel drains when closed");phase(owner,3);phase(owner.root(),3);owner.fluidState.update(false);need(owner.fluidState.outlets()==4&&level.getFluidState(FLOW.north()).isSource(),"resumed opening replenishes flowing outlet");level.removeBlock(FLOW,false);need(level.getBlockState(FLOW.north()).getValue(LiquidBlock.LEVEL)==1,"actual stationary member removal retires owned outlet before tile removal");System.out.println("[vandorlabs][segmented-fluid] flow read PASS separate-process/close/drain/resume/actualremoval");}
    @SubscribeEvent public static void started(ServerStartedEvent event)throws Exception{if(!enabled())return;var level=event.getServer().overworld();if(phase().endsWith("write")){matrix(level);host(level);write(level);}else read(level);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][segmented-fluid] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);}
}
